def tablefill(n,m,trans,acc):
    # distinguishable pair algorithm O(n^2), return equivalence labels
    dist=[[False]*n for _ in range(n)]
    for i in range(n):
        for j in range(i+1,n):
            if acc[i]!=acc[j]:dist[i][j]=dist[j][i]=True
    changed=True
    while changed:
        changed=False
        for i in range(n):
            for j in range(i+1,n):
                if dist[i][j]:continue
                for a in range(m):
                    x,y=trans[i][a],trans[j][a]
                    if x!=y and dist[x][y]:
                        dist[i][j]=dist[j][i]=True;changed=True;break
    # grouping
    groups=[]
    for i in range(n):
        for g in groups:
            if not dist[i][g[0]]:
                g.append(i);break
        else:groups.append([i])
    b=[0]*n
    for k,g in enumerate(groups):
        for s in g:b[s]=k
    return b

def same_partition(a,b):
    n=len(a)
    return all((a[i]==a[j])==(b[i]==b[j]) for i in range(n) for j in range(n))

